using System;using System.IO;using System.Linq;using System.Security.Cryptography;using Mono.Cecil;using Mono.Cecil.Cil;
class PatchShopOS {
static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
static void Main(string[] a){if(Hash(a[0])!="c942daa762f1960c99f9f621687d6c996e1951860cdfbacf618939754565c252")throw new Exception("Unrecognized ShopOS build; refusing rewrite");if(Path.GetFullPath(a[0])==Path.GetFullPath(a[2]))throw new Exception("Output must be isolated");var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(a[3]);using(var x=AssemblyDefinition.ReadAssembly(a[0],new ReaderParameters {AssemblyResolver=resolver}))using(var helper=AssemblyDefinition.ReadAssembly(a[1])){var ht=helper.MainModule.GetType("TCG.NativeCompatibility.NativeToolPaths");var combine=x.MainModule.ImportReference(ht.Methods.Single(m=>m.Name=="Combine"));var fm=x.MainModule.ImportReference(ht.Methods.Single(m=>m.Name=="FileManager"));int count=0;foreach(var t in x.MainModule.Types)foreach(var m in t.Methods){if(!m.HasBody)continue;foreach(var i in m.Body.Instructions){if(t.FullName=="ShopOS.OsMusic"&&new[]{"HasYtdlp","get_Ytdlp","Fetch","Convert","Args"}.Contains(m.Name)){var mr=i.Operand as MethodReference;if(i.OpCode==OpCodes.Call&&mr!=null&&mr.FullName=="System.String System.IO.Path::Combine(System.String,System.String)"&&i.Previous!=null&&i.Previous.OpCode==OpCodes.Ldstr&&new[]{"yt-dlp.exe","qjs.exe","ffmpeg.exe"}.Contains((string)i.Previous.Operand)){i.Operand=combine;count++;}}if(t.FullName=="ShopOS.OsPageWallpaper"&&m.Name=="OpenFolder"&&i.OpCode==OpCodes.Ldstr&&(string)i.Operand=="explorer.exe"){i.OpCode=OpCodes.Call;i.Operand=fm;count++;}}}var music=x.MainModule.GetType("ShopOS.OsMusic");var update=music.Methods.Single(m=>m.Name=="Update");var start=update.Body.Instructions[4];var il=update.Body.GetILProcessor();var guard=new[]{Instruction.Create(OpCodes.Call,x.MainModule.ImportReference(ht.Methods.Single(m=>m.Name=="get_IsMac"))),Instruction.Create(OpCodes.Brfalse,start),Instruction.Create(OpCodes.Call,music.Methods.Single(m=>m.Name=="get_Ytdlp")),Instruction.Create(OpCodes.Call,music.Methods.Single(m=>m.Name=="get_ToolsDir")),Instruction.Create(OpCodes.Call,x.MainModule.ImportReference(ht.Methods.Single(m=>m.Name=="CanSelfUpdate"))),Instruction.Create(OpCodes.Brtrue,start),Instruction.Create(OpCodes.Ret)};foreach(var ins in guard)il.InsertBefore(start,ins);if(count!=6)throw new Exception("Expected6 changes; got "+count);x.Write(a[2]+".tmp");if(File.Exists(a[2]))File.Delete(a[2]);File.Move(a[2]+".tmp",a[2]);Console.WriteLine("Wrote isolated patch with6 call-site changes; input unchanged");}}
}
